<script setup lang="ts">import { computed } from 'vue';import { useCalendarStore } from '../../stores/calendar.store';const c=useCalendarStore();const future=computed(()=>c.sortedEvents.filter(e=>+new Date(e.end||e.start)>=Date.now()).slice(0,100));function day(e:string){return new Date(e).toLocaleDateString('it-IT',{weekday:'short',day:'numeric',month:'long'})}function time(e:string,all:boolean){return all?'Tutto il giorno':new Date(e).toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'})}</script><template><div class="agenda-list"><article v-for="e in future" :key="e.id"><div class="agenda-date"><b>{{day(e.start)}}</b><span>{{time(e.start,e.allDay)}}</span></div><div><h3>{{e.title}}</h3><p v-if="e.location">{{e.location}}</p></div></article><div v-if="!future.length" class="empty">Nessun evento in agenda.</div></div></template><style scoped>.agenda-list{display:grid;gap:.5rem}.agenda-list article{display:grid;grid-template-columns:minmax(120px,180px) 1fr;gap:1rem;padding:1rem;border-bottom:1px solid rgba(255,255,255,.08)}.agenda-date{display:grid;align-content:start}.agenda-date b{text-transform:capitalize}.agenda-date span{color:var(--text-muted);font-size:var(--font-sm)}h3{margin:0;font-size:1rem;font-weight:600}p{margin:.3rem 0 0;color:var(--text-muted);font-size:var(--font-sm)}@media(max-width:600px){.agenda-list article{grid-template-columns:1fr;padding:1rem .3rem;gap:.4rem}.agenda-date{display:flex;justify-content:space-between}}</style>
